      lab: { title: "实验：在单进程模拟 collectives 与分片状态", goal: "用列表模拟 all-reduce、reduce-scatter、all-gather，并验证组合不变量。", file: "/labs/cs336/collectives_sim.py", steps: ["运行四 rank 例子", "更改 world size", "观察通信结果和分片大小"], expected: ["reduce-scatter+all-gather 等于 all-reduce", "每 rank shard 大小一致", "输出 PASS"], sourceNote: "对应 Lectures 7–8 与 A2；不测网络带宽，不实现官方 distributed TODO。" },
